mapper.select:
SELECT id, source_uid, source_type, source_code, display_name, license_status, mdx_path, mdd_path, examples_path, cover_image_path, NULL AS metadata_json, status, created_by, created_at, updated_at FROM data_cleaning_source
source_type = #{sourceType}
ORDER BY updated_at DESC, id DESC

SELECT id, job_uid, source_uid, job_type, status, progress_total, progress_done, NULL AS result_json, error_message, created_by, started_at, finished_at, created_at, updated_at FROM data_cleaning_job
source_uid = #{sourceUid}
AND job_type = #{jobType}
ORDER BY created_at DESC, id DESC LIMIT 100

SELECT id, import_job_uid, dictionary_uid, source_uid, status, import_limit, processed_entries, imported_entries, failed_entries, imported_examples, imported_phrases, error_message, NULL AS result_json, created_by, started_at, finished_at, created_at, updated_at FROM dictionary_import_job
dictionary_uid = #{dictionaryUid}
ORDER BY created_at DESC, id DESC LIMIT 100
